function commitAssignmentChanges(){for(const change of stagedAssignmentChanges){if(change.type==='remove')assignmentLinks=assignmentLinks.filter(x=>!(x[0]===change.faculty&&x[1]===change.course));if(change.type==='add'&&!assignmentLinks.some(x=>x[0]===change.faculty&&x[1]===change.course))assignmentLinks.push([change.faculty,change.course])}stagedAssignmentChanges=[];render()}
