function filterHodPeriodRows(){const semester=document.querySelector("#hodPeriodSemester")?.value||"all",day=document.querySelector("#hodPeriodDay")?.value||"all",query=(document.querySelector("#hodPeriodSlotSearch")?.value||"").toLowerCase();const rows=[...document.querySelectorAll(".hod-period-slot")],filtered=rows.filter(row=>(semester==="all"||row.dataset.semester===semester)&&(day==="all"||row.dataset.day===day));rows.forEach(row=>{row.hidden=!filtered.includes(row)||!row.textContent.toLowerCase().includes(query)});const total=document.querySelector("#hodPeriodTotalSlots"),marked=document.querySelector("#hodPeriodMarkedSlots"),pending=document.querySelector("#hodPeriodPendingSlots");if(total)total.textContent=filtered.length;if(marked)marked.textContent=filtered.filter(row=>row.querySelector(".badge:not(.warn)")) .length;if(pending)pending.textContent=filtered.length-filtered.filter(row=>row.querySelector(".badge:not(.warn)")).length}
document.addEventListener("click",e=>{const card=e.target.closest("[data-period-slot]");if(!card||roleKey!=="hod"||active!=="period")return;selectHodPeriodSlot(Number(card.dataset.periodSlot))});
document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches("[data-period-slot]")){e.preventDefault();selectHodPeriodSlot(Number(e.target.dataset.periodSlot))}});
function selectHodPeriodSlot(index){const data=[{code:"CS 203",title:"Data Structures & Algorithms",period:1,semester:3,day:"Monday",time:"09:30–10:30",date:document.querySelector("#hodPeriodDate")?.value,marked:true,present:2,absent:1},{code:"CS 211",title:"Discrete Mathematics",period:2,semester:3,day:"Monday",time:"10:30–11:30",date:document.querySelector("#hodPeriodDate")?.value,marked:false,present:0,absent:0},{code:"CS 220",title:"Web Technologies",period:3,semester:2,day:"Tuesday",time:"11:30–12:30",date:document.querySelector("#hodPeriodDate")?.value,marked:true,present:2,absent:1},{code:"CS 208",title:"Database Systems",period:4,semester:3,day:"Wednesday",time:"13:30–14:30",date:document.querySelector("#hodPeriodDate")?.value,marked:false,present:0,absent:0}][index];if(!data)return;document.querySelectorAll("[data-period-slot]").forEach((node,i)=>node.classList.toggle("selected",i===index));const roster=data.marked?[["Akhil Thomas","KU24CS018","Present"],["Riya Das","KU24CS031","Present"],["Nikhil P.","KU24CS009","Absent"],["Diya Raj","KU24CS012","Unmarked"]]:[["Akhil Thomas","KU24CS018","Unmarked"],["Riya Das","KU24CS031","Unmarked"],["Nikhil P.","KU24CS009","Unmarked"],["Diya Raj","KU24CS012","Unmarked"]],present=roster.filter(x=>x[2]==="Present").length,absent=roster.filter(x=>x[2]==="Absent").length,unmarked=roster.filter(x=>x[2]==="Unmarked").length,panel=document.querySelector("#hodPeriodRosterPanel");panel.innerHTML=`<div class="panel-header"><div><h2 class="panel-title">${data.code} · Period ${data.period}</h2><p class="panel-subtitle">${data.title} · ${data.day} · ${data.time} · Sem ${data.semester} · Date: ${data.date}</p></div></div><div class="hod-summary-strip"><span>Enrolled <b>${roster.length}</b></span><span>Present <b>${present}</b></span><span>Absent <b>${absent}</b></span><span>Unmarked <b>${unmarked}</b></span></div><div class="hod-period-roster-controls"><input id="hodPeriodRosterSearch" class="hod-inline-search" placeholder="Search enrolled students..."><select id="hodPeriodStatus"><option value="all">All Statuses</option><option value="present">Present Only</option><option value="absent">Absent Only</option><option value="unmarked">Unmarked Only</option></select></div>${rowsTable(["#","STUDENT NAME","CAP / ID","STATUS"],roster.map((row,i)=>[`<span>${i+1}</span>`,row[0],row[1],badge(row[2],row[2]==="Absent"?"red":row[2]==="Unmarked"?"warn":"")]))}`;filterHodPeriodRoster()}
document.addEventListener("input",e=>{if(e.target.id==="hodPeriodRosterSearch")filterHodPeriodRoster()});document.addEventListener("change",e=>{if(e.target.id==="hodPeriodStatus")filterHodPeriodRoster()});
document.addEventListener("change",e=>{if(e.target.id==="hodPeriodDate"){const selected=document.querySelector("[data-period-slot].selected");if(selected)selectHodPeriodSlot(Number(selected.dataset.periodSlot))}});
function filterHodPeriodRoster(){const q=(document.querySelector("#hodPeriodRosterSearch")?.value||"").toLowerCase(),status=document.querySelector("#hodPeriodStatus")?.value||"all";document.querySelectorAll("#hodPeriodRosterPanel tbody tr").forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(q)||(status!=="all"&&!row.textContent.toLowerCase().includes(status))})}

document.addEventListener("change",e=>{if(!["staffSemester","staffDepartment","staffCourse"].includes(e.target.id))return;const semester=document.querySelector("#staffSemester"),department=document.querySelector("#staffDepartment"),course=document.querySelector("#staffCourse");if(e.target===semester||e.target===department){[...course.options].forEach(option=>{if(!option.value)return;option.hidden=(semester.value!=="all"&&option.dataset.sem!==semester.value)||(department.value!=="all"&&option.dataset.dept!==department.value)});if(course.selectedOptions[0]?.hidden){course.value="";renderStaffRoster("")}}else renderStaffRoster(course.value)});
function renderStaffRoster(courseId){const panel=document.querySelector("#staffRosterPanel");if(!panel)return;if(!courseId){panel.innerHTML='<div class="hod-empty-state">Select a paper/course to inspect its enrolled students.</div>';return}const courses={cs203:["Data Structures & Algorithms","CS 203",0,[["Nikhil P.","Computer Science","CS"],["Diya Raj","Computer Science","CS"],["Akhil Thomas","Mathematics","MAT"],["Fathima K.","Computer Science","CS"]]],cs220:["Web Technologies","CS 220",0,[["Diya Raj","Computer Science","CS"],["Akhil Thomas","Computer Science","CS"],["Fathima K.","Mathematics","MAT"]]],cs208:["Database Systems","CS 208",0,[["Nikhil P.","Computer Science","CS"],["Muneer K.","Computer Science","CS"]]],hum312:["Digital Humanities","HUM 312",0,[["Akhil Thomas","Computer Science","CS"],["Fathima K.","Mathematics","MAT"]]],mat310:["Applied Statistics","MAT 310",0,[["Diya Raj","Mathematics","MAT"],["Nikhil P.","Computer Science","CS"]]]},course=courses[courseId];if(!course)return;const [title,code,_listedCount,students]=course,total=course[3].length,departments={};students.forEach(student=>departments[student[1]]=(departments[student[1]]||0)+1);panel.innerHTML=`<div class="panel-header"><div><h2 class="panel-title">${title}</h2><p class="panel-subtitle">${code}</p></div></div><div class="stat-grid">${stat('Enrolled Students',total,'Selected paper roster','♙')}${stat('Departments',Object.keys(departments).length,'Student department breakdown','▤')}</div><section class="panel"><div class="panel-header"><h2 class="panel-title">Department Breakdown</h2></div>${Object.entries(departments).map(([name,count])=>`<div class="summary-row"><span>${name}</span><b>${count} students</b></div>`).join('')}</section><section class="panel"><div class="panel-header"><h2 class="panel-title">Enrolled Students (${total})</h2><select id="staffRosterDepartment"><option value="all">All Departments (${total})</option>${Object.entries(departments).map(([name,count])=>`<option value="${name}">${name} (${count})</option>`).join('')}</select></div>${rowsTable(['#','STUDENT NAME','DEPARTMENT'],students.map((student,i)=>[i+1,student[0],`<span class="badge neutral" data-department="${student[1]}">${student[2]}</span>`]))}</section>`}

let directorPromotionStep=0;document.addEventListener("click",e=>{const preset=e.target.closest("[data-preset-days]");if(preset){const date=new Date();date.setDate(date.getDate()+Number(preset.dataset.presetDays));date.setHours(23,59,0,0);const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);const input=document.querySelector("#directorDeadline");if(input)input.value=local.toISOString().slice(0,16);return}const action=e.target.closest("[data-action]")?.dataset.action;if(!action||roleKey!=="director"||active!=="promotion")return;e.stopImmediatePropagation();const stage=document.querySelector("#directorPromotionStage");if(action==="promotionStart"){directorPromotionStep=1;stage.innerHTML='<div class="promotion-last"><b>📅 Last Promotion</b><span>Never promoted on this system</span></div><p>Please verify the date above before continuing. Only proceed if you intend to start a new semester now.</p><div class="director-actions"><button class="btn btn-primary" data-action="promotionContinue">Continue →</button><button class="btn btn-secondary" data-action="promotionCancel">Cancel</button></div>'}else if(action==="promotionContinue"){directorPromotionStep=2;stage.innerHTML='<div class="inline-notice"><b>⚠ Has the next semester officially started?</b><p>This will increment every student’s semester by 1 and permanently remove Semester 10 graduates.</p></div><div class="director-actions"><button class="btn btn-danger" data-action="promote">Yes, Start New Semester →</button><button class="btn btn-secondary" data-action="promotionCancel">No, Cancel</button></div>'}else if(action==="promotionCancel"){directorPromotionStep=0;stage.innerHTML='<button class="btn btn-primary" data-action="promotionStart">Promote All Students →</button>'}},true);

document.addEventListener("change",e=>{if(e.target.name==="academicTrack"){studentSelectedTrack=e.target.value;document.querySelectorAll(".pathway-choice").forEach(card=>card.classList.toggle("selected",card.querySelector("input")?.checked))}if(e.target.id==="adminLogType"||e.target.id==="adminLogStatus"){const type=document.querySelector("#adminLogType")?.value||"all",status=document.querySelector("#adminLogStatus")?.value||"all";document.querySelectorAll("#content tbody tr").forEach(row=>{const text=row.textContent.toLowerCase(),typeMatch=type==="all"||text.includes(type),statusMatch=status==="all"||text.includes(status);row.hidden=!typeMatch||!statusMatch})}if(e.target.id==="adminFacultyRole"){const field=document.querySelector("[data-faculty-department]");if(field)field.style.display=e.target.value==="hod"?"block":"none"}if(e.target.name==="teacherPdfMode"||e.target.classList.contains("teacher-pdf-dept")){const specific=document.querySelector("input[name=teacherPdfMode]:checked")?.value==="specific",boxes=[...document.querySelectorAll(".teacher-pdf-dept")];boxes.forEach(x=>{x.disabled=!specific;if(!specific)x.checked=true});const count=specific?boxes.filter(x=>x.checked).reduce((n,x)=>n+Number(x.value),0):4;const label=document.querySelector("#teacherPdfCount"),confirm=document.querySelector("#modalConfirm");if(label)label.textContent=`${count} of 4`;if(confirm&&confirm.dataset.action==="teacherPdf")confirm.textContent=`Download PDF (${count})`}if(e.target.id==="teacherScheduleDate"){const label=document.querySelector("#teacherSelectedDate");if(label)label.textContent=e.target.value}if(e.target.id==="teacherTimetableDay"||e.target.id==="teacherTimetableSemester"){const day=document.querySelector("#teacherTimetableDay")?.value||"all",sem=document.querySelector("#teacherTimetableSemester")?.value||"all";document.querySelectorAll("[data-teacher-day]").forEach(row=>{const dayMatch=day==="all"||row.dataset.teacherDay===day,semMatch=sem==="Semester 3"||sem==="all";row.hidden=!dayMatch||!semMatch})}if(e.target.id==="teacherRosterSemester"){const select=document.querySelector("#teacherRosterCourse");[...select.options].forEach(option=>{if(!option.value)return;option.hidden=e.target.value!=="all"&&option.dataset.sem!==e.target.value.replace("Semester ","")});if(select.selectedOptions[0]?.hidden){select.value="";renderTeacherRoster("")}}if(e.target.id==="teacherRosterCourse")renderTeacherRoster(e.target.value)});
document.addEventListener("click",e=>{if(roleKey==="teacher"&&active==="schedule"&&e.target.closest("[data-action=teacherToday]")){const input=document.querySelector("#teacherScheduleDate"),label=document.querySelector("#teacherSelectedDate"),today=new Date().toISOString().slice(0,10);if(input)input.value=today;if(label)label.textContent=today}const all=e.target.closest("[data-mark-all]");if(all){document.querySelectorAll(".teacher-mark-toggle").forEach(button=>setTeacherMark(button,all.dataset.markAll));updateTeacherAttendanceCounts()}const row=e.target.closest("[data-mark-student]");if(row){setTeacherMark(row,row.textContent.includes("PRESENT")?"absent":"present");updateTeacherAttendanceCounts()};const departmentSelect=panel.querySelector("#staffRosterDepartment");departmentSelect?.addEventListener("change",()=>{const value=departmentSelect.value;panel.querySelectorAll("tbody tr").forEach(row=>row.hidden=value!=="all"&&row.querySelector("[data-department]")?.dataset.department!==value)})});
function setTeacherMark(button,status){const absent=status==="absent";button.textContent=absent?"✗ ABSENT":"✓ PRESENT";button.classList.toggle("is-absent",absent)}function updateTeacherAttendanceCounts(){const buttons=[...document.querySelectorAll(".teacher-mark-toggle")],absent=buttons.filter(x=>x.classList.contains("is-absent")).length,present=buttons.length-absent,p=document.querySelector("#teacherPresentCount"),a=document.querySelector("#teacherAbsentCount");if(p)p.textContent=present;if(a)a.textContent=absent;const confirm=document.querySelector("#modalConfirm");if(confirm&&confirm.dataset.action==="teacherAttendance")confirm.textContent=`Save & Submit (${present} Present, ${absent} Absent) →`}
function renderTeacherRoster(id){const container=document.querySelector("#teacherRosterDetails");if(!container)return;if(!id){container.innerHTML='<div class="hod-empty-state">Select an assigned paper to view its class roster.</div>';return}const course=id==="cs203"?['Data Structures & Algorithms','CS 203',3]:id==="cs211"?['Discrete Mathematics','CS 211',3]:['Web Technologies','CS 220',2],students=[['Nikhil P.','Computer Science','CS'],['Diya Raj','Computer Science','CS'],['Akhil Thomas','Mathematics','MAT'],['Riya Das','Computer Science','CS']],departments={};students.forEach(x=>departments[x[1]]=(departments[x[1]]||0)+1);container.innerHTML=`<div class="panel-header"><div><h2 class="panel-title">${course[0]}</h2><p class="panel-subtitle">${course[1]}</p></div><button class="btn btn-secondary" data-action="teacherPdf" data-course="${course[0]} (${course[1]})">Export Attendance Sheet (PDF)</button></div><div class="stat-grid">${stat('Enrolled Students',students.length,'Selected course roster','♙')}${stat('Departments',Object.keys(departments).length,'Department breakdown','▤')}</div>${panel('Department Breakdown',Object.entries(departments).map(([name,count])=>`<div class="summary-row"><span>${name}</span><b>${count} students</b></div>`).join(''))}<div class="panel-header"><h2 class="panel-title">Class Roster (${students.length})</h2><select id="teacherRosterDepartment"><option value="all">All Departments</option>${Object.keys(departments).map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div>${rowsTable(['#','STUDENT NAME','DEPARTMENT'],students.map((x,i)=>[i+1,x[0],`<span class="badge neutral" data-department="${x[1]}">${x[2]}</span>`]))}`;const departmentSelect=container.querySelector('#teacherRosterDepartment');departmentSelect?.addEventListener('change',()=>{const value=departmentSelect.value;container.querySelectorAll('tbody tr').forEach(row=>row.hidden=value!=='all'&&row.querySelector('[data-department]')?.dataset.department!==value)})}
